/******************************************************************************
 * MelroseOS Enterprise
 * Dependency-Aware System Auditor
 * File: AUD-03_DependencyAwareAuditor.gs
 * Version: 2.0.0
 *
 * SAFETY:
 *   REPORT ONLY. Does not delete, rename, move, archive, or clear production tabs.
 *
 * Requires:
 *   AUD-04_DependencyRegistry.gs generated by the v2 installer.
 ******************************************************************************/

const AUD2 = {
  VERSION: "2.0.0",
  WORKBOOKS: {
    CORE: "1W-32zYjyttQQS81UnvzJFz9yhp58YUKpTM0Kw0bfK64",
    CRM: "1QpgjJEMpW4wW_xNUY7S3EQh4yqvU8P1y2eNZ4oJlOq8",
    MARKETING: "1MnWLm3aK1D8KDmqNnkcsUmiBnFyjKlQcOtVwbeaMldo",
    WEBSITE: "1Ml9wEEz_gi30i8Js3iMJeycYy_nnrVv6KYD22g9aVhc",
    ANALYTICS: "1OMqOY9trsL0r46BY0tg023mpq9i3SpbX3kNSnMvZsPU",
    ARCHIVE: "1uRai34TuOVNKKZ2TJKXkfaw03bd8uqlD8RQTALXv2lk"
  },
  INVENTORY: "AUD2_DEPENDENCY_INVENTORY",
  ACTIONS: "AUD2_CLEANUP_REVIEW",
  PROTECTED_PREFIXES: [
    "AE_","LI_","NF_","AP_","CO_","OP_","AC_","AUD_","AUD2_"
  ]
};

function AUD2_runDependencyAudit() {
  const core = SpreadsheetApp.openById(AUD2.WORKBOOKS.CORE);

  const inventory = AUD2_reset_(core, AUD2.INVENTORY, [
    "Workbook","SpreadsheetID","SheetName","Rows","Columns","HasData",
    "LiteralReference","GetSheetReference","ConstantReference",
    "CrossWorkbookReference","TriggerRelated","ProtectedPrefix",
    "ReferenceProjects","Evidence","Classification","RecommendedAction",
    "Confidence","AuditedAt"
  ]);

  const actions = AUD2_reset_(core, AUD2.ACTIONS, [
    "Workbook","SheetName","Classification","RecommendedAction",
    "Confidence","Evidence","ApprovalStatus","ApprovedBy","ApprovedAt"
  ]);

  const registry =
    typeof AUD2_DEPENDENCY_REGISTRY !== "undefined"
      ? AUD2_DEPENDENCY_REGISTRY
      : {projects:{}, triggers:[]};

  const inventoryRows = [];
  const actionRows = [];

  Object.keys(AUD2.WORKBOOKS).forEach(function(workbookName) {
    const spreadsheetId = AUD2.WORKBOOKS[workbookName];
    const ss = SpreadsheetApp.openById(spreadsheetId);

    ss.getSheets().forEach(function(sheet) {
      const name = sheet.getName();
      const evidence = AUD2_evidence_(name, workbookName, registry);
      const classification = AUD2_classify_(name, sheet, evidence);
      const action = AUD2_action_(classification);
      const confidence = AUD2_confidence_(classification, evidence);

      inventoryRows.push([
        workbookName,
        spreadsheetId,
        name,
        sheet.getLastRow(),
        sheet.getLastColumn(),
        sheet.getLastRow() > 1 || sheet.getLastColumn() > 1,
        evidence.literal,
        evidence.getSheet,
        evidence.constant,
        evidence.crossWorkbook,
        evidence.triggerRelated,
        evidence.protectedPrefix,
        evidence.projects.join(", "),
        evidence.details.join(" | "),
        classification,
        action,
        confidence,
        new Date()
      ]);

      if (classification !== "PROTECTED_ACTIVE") {
        actionRows.push([
          workbookName,
          name,
          classification,
          action,
          confidence,
          evidence.details.join(" | "),
          "PENDING_REVIEW",
          "",
          ""
        ]);
      }
    });
  });

  if (inventoryRows.length) {
    inventory.getRange(2,1,inventoryRows.length,inventoryRows[0].length)
      .setValues(inventoryRows);
  }

  if (actionRows.length) {
    actions.getRange(2,1,actionRows.length,actionRows[0].length)
      .setValues(actionRows);
  }

  inventory.setFrozenRows(1);
  actions.setFrozenRows(1);
  inventory.autoResizeColumns(1, inventory.getLastColumn());
  actions.autoResizeColumns(1, actions.getLastColumn());

  return AUD2_summary_();
}

function AUD2_evidence_(sheetName, workbookName, registry) {
  const result = {
    literal:false,
    getSheet:false,
    constant:false,
    crossWorkbook:false,
    triggerRelated:false,
    protectedPrefix:false,
    projects:[],
    details:[]
  };

  const upper = String(sheetName || "").toUpperCase();

  result.protectedPrefix = AUD2.PROTECTED_PREFIXES.some(function(prefix) {
    return upper.indexOf(prefix) === 0;
  });

  if (result.protectedPrefix) {
    result.details.push("Protected MelroseOS module prefix.");
  }

  const projects = registry.projects || {};

  Object.keys(projects).forEach(function(project) {
    const p = projects[project] || {};
    let matched = false;

    if ((p.literalSheetNames || []).indexOf(sheetName) !== -1) {
      result.literal = true;
      matched = true;
      result.details.push(project + ": literal sheet-name reference.");
    }

    if ((p.getSheetNames || []).indexOf(sheetName) !== -1) {
      result.getSheet = true;
      matched = true;
      result.details.push(project + ": getSheetByName reference.");
    }

    if ((p.constantValues || []).indexOf(sheetName) !== -1) {
      result.constant = true;
      matched = true;
      result.details.push(project + ": constant/config value reference.");
    }

    if ((p.crossWorkbookSheetNames || []).indexOf(sheetName) !== -1) {
      result.crossWorkbook = true;
      matched = true;
      result.details.push(project + ": cross-workbook sheet reference.");
    }

    if (matched && result.projects.indexOf(project) === -1) {
      result.projects.push(project);
    }
  });

  const triggers = registry.triggers || [];
  triggers.forEach(function(trigger) {
    const source = String(trigger.source || "");
    const handler = String(trigger.handler || "");
    const sheets = trigger.sheetNames || [];

    if (sheets.indexOf(sheetName) !== -1) {
      result.triggerRelated = true;
      result.details.push(
        "Trigger dependency: " + handler + " (" + source + ")."
      );
    }
  });

  return result;
}

function AUD2_classify_(name, sheet, e) {
  const upper = String(name || "").toUpperCase();
  const hasDependency =
    e.literal || e.getSheet || e.constant ||
    e.crossWorkbook || e.triggerRelated ||
    e.protectedPrefix;

  if (hasDependency) {
    return "PROTECTED_ACTIVE";
  }

  if (
    /(_PREMIGRATION_|PREMIGRATION|_OLD_|^OLD_|LEGACY|DEPRECATED|OBSOLETE)/
      .test(upper)
  ) {
    return "ARCHIVE_SAFE";
  }

  if (
    /(^|[_\-\s])(TEST|DEMO|SAMPLE|SANDBOX|TMP|TEMP)([_\-\s]|$)/
      .test(upper)
  ) {
    return "DELETE_SAFE";
  }

  if (
    upper === "SHEET1" &&
    sheet.getLastRow() <= 1 &&
    sheet.getLastColumn() <= 1
  ) {
    return "DELETE_SAFE";
  }

  return "MANUAL_REVIEW";
}

function AUD2_action_(classification) {
  switch (classification) {
    case "PROTECTED_ACTIVE":
      return "KEEP_LOCKED";
    case "ARCHIVE_SAFE":
      return "REVIEW_THEN_ARCHIVE";
    case "DELETE_SAFE":
      return "BACKUP_THEN_DELETE";
    default:
      return "MANUAL_REVIEW_ONLY";
  }
}

function AUD2_confidence_(classification, e) {
  if (classification === "PROTECTED_ACTIVE") {
    if (
      e.getSheet || e.constant ||
      e.crossWorkbook || e.triggerRelated
    ) {
      return "HIGH";
    }
    return "MEDIUM";
  }

  if (
    classification === "ARCHIVE_SAFE" ||
    classification === "DELETE_SAFE"
  ) {
    return "MEDIUM";
  }

  return "LOW";
}

function AUD2_reset_(ss, name, headers) {
  let sheet = ss.getSheetByName(name);
  if (!sheet) sheet = ss.insertSheet(name);
  sheet.clearContents();
  sheet.getRange(1,1,1,headers.length).setValues([headers]);
  return sheet;
}

function AUD2_summary_() {
  const ss = SpreadsheetApp.openById(AUD2.WORKBOOKS.CORE);
  const sheet = ss.getSheetByName(AUD2.INVENTORY);

  const result = {
    success:true,
    version:AUD2.VERSION,
    totalSheets:0,
    classifications:{},
    destructiveActionsPerformed:false
  };

  if (!sheet || sheet.getLastRow() < 2) return result;

  const values = sheet.getDataRange().getValues();
  const headers = values.shift();
  const index = headers.indexOf("Classification");

  result.totalSheets = values.length;

  values.forEach(function(row) {
    const c = String(row[index] || "UNKNOWN");
    result.classifications[c] =
      (result.classifications[c] || 0) + 1;
  });

  return result;
}

function AUD2_testDependencyAuditor() {
  const result = AUD2_runDependencyAudit();
  Logger.log(JSON.stringify(result));

  if (!result.success) {
    throw new Error("Dependency-Aware Auditor v2 failed.");
  }

  return true;
}
